"""regression_mlp - training script generated by AI Made Easy."""
import time

import numpy as np
import torch
import torch.nn as nn
from torch.utils.data import DataLoader, TensorDataset

# ------------------------------------------------------------------ config
SEED = 42
DEVICE = "auto"
EPOCHS = 25
BATCH_SIZE = 32
EARLY_STOP = 5
VAL_FRACTION = 0.1
TEST_FRACTION = 0.1
NUM_WORKERS = 0
PIN_MEMORY = True
CHECKPOINT = "regression_mlp_best.pt"
INPUT_SHAPE = (20,)

def pick_device() -> str:
    if DEVICE != "auto":
        return DEVICE
    if torch.backends.mps.is_available():
        return "mps"
    if torch.cuda.is_available():
        return "cuda"
    return "cpu"


# ------------------------------------------------------------------- model
class RegressionMlp(nn.Module):
    def __init__(self):
        super().__init__()
        self.dense_1 = nn.Linear(in_features=20, out_features=64, bias=True)
        self.layer_norm_1 = nn.LayerNorm(normalized_shape=[64], eps=1e-05)
        self.relu_1 = nn.ReLU()
        self.dense_2 = nn.Linear(in_features=64, out_features=32, bias=True)
        self.relu_2 = nn.ReLU()
        self.dense_3 = nn.Linear(in_features=32, out_features=1, bias=True)

    def forward(self, x):
        v_dense_1 = self.dense_1(x)
        v_layer_norm_1 = self.layer_norm_1(v_dense_1)
        v_relu_1 = self.relu_1(v_layer_norm_1)
        v_dense_2 = self.dense_2(v_relu_1)
        v_relu_2 = self.relu_2(v_dense_2)
        v_dense_3 = self.dense_3(v_relu_2)
        return v_dense_3


# ----------------------------------------------------------------- dataset

def make_arrays():
    """Synthetic regression data"""
    rng = np.random.default_rng(SEED)
    n, d = 2000, 20
    w = rng.normal(size=d)
    x = rng.normal(size=(n, d)).astype(np.float32)
    y = (x @ w + rng.normal(0, 0.1, n)).astype(np.float32)
    return x, y


def make_loaders(device_hint: str):
    x, y = make_arrays()
    lo, hi = x.min(axis=0), x.max(axis=0)
    x = (x - lo) / (hi - lo + 1e-12) * (1.0 - -1.0) + -1.0
    x = x.astype(np.float32)
    y = y.astype(np.float32)
    n = len(x)
    idx = np.random.default_rng(SEED).permutation(n)
    n_val = int(n * VAL_FRACTION)
    n_test = int(n * TEST_FRACTION)
    val_i = idx[:n_val]
    test_i = idx[n_val:n_val + n_test]
    train_i = idx[n_val + n_test:]
    mk = lambda ids: DataLoader(
        TensorDataset(torch.from_numpy(x[ids]), torch.from_numpy(y[ids])),
        batch_size=BATCH_SIZE, shuffle=True,
        num_workers=NUM_WORKERS, pin_memory=PIN_MEMORY)
    return mk(train_i), mk(val_i), mk(test_i)




@torch.no_grad()
def evaluate(model, loss_fn, loader, device):
    model.eval()
    total, n_seen = 0.0, 0
    abs_sum = sq_sum = 0.0
    for xb, yb in loader:
        xb, yb = xb.to(device), yb.to(device)
        out = model(xb)
        err = out.squeeze(-1) - yb
        total += err.pow(2).sum().item()
        abs_sum += err.abs().sum().item()
        sq_sum += err.pow(2).sum().item()
        n_seen += len(yb)
    metrics = {}
    metrics["mse"] = sq_sum / max(n_seen, 1)
    metrics["mae"] = abs_sum / max(n_seen, 1)
    return total / max(n_seen, 1), metrics




def main():
    torch.manual_seed(SEED)
    np.random.seed(SEED)
    device = torch.device(pick_device())
    print(f"device: {device}")
    train_loader, val_loader, test_loader = make_loaders(str(device))
    model = RegressionMlp().to(device)
    print(f"parameters: {sum(p.numel() for p in model.parameters()):,}")
    loss_fn = nn.SmoothL1Loss(beta=1.0)
    optimizer = torch.optim.Adam(model.parameters(), lr=0.001, betas=(0.9, 0.999), eps=1e-08)
    scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(optimizer, T_max=50, eta_min=1e-06)
    best_val, best_state, bad_epochs = float("inf"), None, 0
    for epoch in range(1, EPOCHS + 1):
        model.train()
        t0, running = time.time(), 0.0
        for xb, yb in train_loader:
            xb, yb = xb.to(device), yb.to(device)
            optimizer.zero_grad()
            loss = loss_fn(model(xb), yb)
            loss.backward()
            optimizer.step()
            running += loss.item() * len(xb)
        train_loss = running / len(train_loader.dataset)
        val_loss, val_metrics = evaluate(model, loss_fn, val_loader, device)
        scheduler.step()
        extra = " ".join(f"{k}={v:.4f}" if isinstance(v, float) else f"{k}={v}"
                         for k, v in val_metrics.items())
        print(f"epoch {epoch}/{EPOCHS} train_loss={train_loss:.4f} "
              f"val_loss={val_loss:.4f} {extra} ({time.time() - t0:.1f}s)")
        if val_loss < best_val:
            best_val, bad_epochs = val_loss, 0
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
        else:
            bad_epochs += 1
            if EARLY_STOP and bad_epochs >= EARLY_STOP:
                print(f"early stopping after {epoch} epochs without improvement")
                break
    if best_state is not None:
        model.load_state_dict(best_state)
    test_loss, test_metrics = evaluate(model, loss_fn, test_loader, device)
    print("test:", {**test_metrics, "loss": round(test_loss, 4)})
    torch.save(model.state_dict(), CHECKPOINT)
    print(f"saved best weights to {CHECKPOINT}")


if __name__ == "__main__":
    main()
